import{_ as a,o as t,c as i,a0 as s}from"./chunks/framework.K3sFe4KB.js";const m=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),o={name:"explanation/decisions.md"};function n(r,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the load-bearing decisions, each with the alternative it beat and the consequence it carries. The contracts live in <code>project/adrs/</code> — ADR-0001 (foundational architecture), ADR-0002 (reconciliation contracts); read those before touching apply semantics.</p><h2 id="plan-apply-drift-over-crud" tabindex="-1">Plan/apply/drift over CRUD <a class="header-anchor" href="#plan-apply-drift-over-crud" aria-label="Permalink to &quot;Plan/apply/drift over CRUD&quot;">​</a></h2><p><strong>Decision:</strong> calendars reconcile desired-state YAML against recorded + live state, like infrastructure — not imperative create/update calls.</p><ul><li><em>Alternative:</em> SDK-style CRUD (<code>events.create</code>, <code>events.update</code>).</li><li><em>Consequence:</em> stable ids + recorded state make re-runs idempotent and drift detectable; the cost is the three-state model every user must learn. See <a href="./plan-apply-drift.html">Plan, apply and drift</a>.</li></ul><h2 id="a-pure-core-behind-ports" tabindex="-1">A pure core behind ports <a class="header-anchor" href="#a-pure-core-behind-ports" aria-label="Permalink to &quot;A pure core behind ports&quot;">​</a></h2><p><strong>Decision:</strong> <code>cicada-core</code> has zero I/O — seven port traits (provider, state, auth, clock, logger, secret, http) with adapters in sibling crates.</p><ul><li><em>Alternative:</em> provider logic inside the CLI/MCP shells.</li><li><em>Consequence:</em> CLI, ops, and MCP surfaces dispatch identical use cases; the whole domain tests against in-memory fakes. Cost: every side effect crosses a trait boundary.</li></ul><h2 id="the-cicada-command-is-a-tamias-shim" tabindex="-1">The <code>cicada</code> command is a tamias shim <a class="header-anchor" href="#the-cicada-command-is-a-tamias-shim" aria-label="Permalink to &quot;The `cicada` command is a tamias shim&quot;">​</a></h2><p><strong>Decision:</strong> no <code>[[bin]]</code> in <code>cicada-cli</code> — the command ships as <code>libraries/cicada</code> (<code>bins[]</code> → <code>tamias-driver-cicada cli</code>), and <code>tamias-driver-cicada mcp</code> renders the ops manifest as MCP tools.</p><ul><li><em>Alternative:</em> a hand-rolled binary plus a bespoke <code>cicada-mcp</code>.</li><li><em>Consequence:</em> one engine, three surfaces (argv, ops, MCP) with zero logic duplication; distribution rides tamias like every org tool. T-019 deleted <code>cicada-mcp</code> for exactly this reason.</li></ul><h2 id="plandigest-instead-of-session-state" tabindex="-1">planDigest instead of session state <a class="header-anchor" href="#plandigest-instead-of-session-state" aria-label="Permalink to &quot;planDigest instead of session state&quot;">​</a></h2><p><strong>Decision:</strong> the preview→apply gate persists issued digests beside the state file; <code>apply --plan-digest</code> enforces issued + unspent + still-matching.</p><ul><li><em>Alternative:</em> cicada-mcp&#39;s in-session digest (deleted, T-019).</li><li><em>Consequence:</em> the gate survives process boundaries and rides ordinary <code>cli.*</code> ops — any surface can enforce it without shared session state.</li></ul><h2 id="mutations-are-confirmation-gated" tabindex="-1">Mutations are confirmation-gated <a class="header-anchor" href="#mutations-are-confirmation-gated" aria-label="Permalink to &quot;Mutations are confirmation-gated&quot;">​</a></h2><p><strong>Decision:</strong> <code>apply</code> prompts unless <code>--auto-approve</code>; wire ops fail closed (null stdin ⇒ abort); <code>provider.add</code> never becomes an op because OAuth needs stdin/browser.</p><ul><li><em>Alternative:</em> trust the caller.</li><li><em>Consequence:</em> agents can plan freely but apply only with explicit consent params — the same gate humans get.</li></ul>',17)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
